1	/**
2	 * E2E test: creates a test customer, funds the wallet, orders a VPS
3	 * (same DB operations the orderServer action performs), then waits for
4	 * the worker to provision it and prints connection details.
5	 */
6	import { PrismaClient } from "@prisma/client";
7	import bcrypt from "bcryptjs";
8	
9	const db = new PrismaClient();
10	
11	async function main() {
12	  const email = "e2e-test@nxeon.local";
13	  let user = await db.user.findUnique({ where: { email } });
14	  if (!user) {
15	    user = await db.user.create({
16	      data: {
17	        email,
18	        name: "E2E Test",
19	        passwordHash: await bcrypt.hash("e2e-test-password", 12),
20	        balanceCents: 1000,
21	      },
22	    });
23	  }
24	
25	  const plan = await db.plan.findUnique({ where: { slug: "nano" } });
26	  const os = await db.osTemplate.findUnique({ where: { slug: "ubuntu-24-04" } });
27	  if (!plan || !os) throw new Error("seed data missing");
28	
29	  const server = await db.$transaction(async (tx) => {
30	    await tx.user.update({ where: { id: user!.id }, data: { balanceCents: { decrement: plan.priceCents } } });
31	    await tx.walletTransaction.create({
32	      data: { userId: user!.id, amountCents: -plan.priceCents, description: "E2E order" },
33	    });
34	    const s = await tx.server.create({
35	      data: {
36	        name: "e2e-test",
37	        hostname: "e2e-test",
38	        userId: user!.id,
39	        planId: plan.id,
40	        osTemplateId: os.id,
41	        expiresAt: new Date(Date.now() + 30 * 86400_000),
42	      },
43	    });
44	    await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
45	    return s;
46	  });
47	
48	  console.log(`ordered server ${server.id}, waiting for worker...`);
49	  const deadline = Date.now() + 10 * 60_000;
50	  for (;;) {
51	    const s = await db.server.findUnique({ where: { id: server.id } });
52	    if (!s) throw new Error("server vanished");
53	    process.stdout.write(`  status=${s.status} vmid=${s.vmid ?? "-"}\r`);
54	    if (s.status === "RUNNING") {
55	      console.log(`\nRESULT ip=${s.ipAddress} sshPort=${s.sshPort} password=${s.rootPassword} vmid=${s.vmid}`);
56	      break;
57	    }
58	    if (s.status === "ERROR") {
59	      const job = await db.job.findFirst({ where: { serverId: s.id }, orderBy: { createdAt: "desc" } });
60	      throw new Error(`provisioning failed: ${job?.error}`);
61	    }
62	    if (Date.now() > deadline) throw new Error("timeout");
63	    await new Promise((r) => setTimeout(r, 5000));
64	  }
65	}
66	
67	main().finally(() => db.$disconnect());
68

1	// Throwaway screenshot capture for blog imagery.
2	// Captures polished public showcase UI from https://nxeon.cloud into
3	// public/blog/screenshots/*.png. CAPTURE-ONLY — no deploy/prisma/restart.
4	//
5	//   node scripts/capture-screens.mjs
6	//
7	import { chromium } from "playwright";
8	import { mkdirSync, statSync, existsSync, unlinkSync } from "node:fs";
9	import { fileURLToPath } from "node:url";
10	import { dirname, join } from "node:path";
11	
12	const ROOT = dirname(dirname(fileURLToPath(import.meta.url)));
13	const OUT = join(ROOT, "public", "blog", "screenshots");
14	const BASE = process.env.BASE_URL || "https://nxeon.cloud";
15	mkdirSync(OUT, { recursive: true });
16	
17	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
18	
19	// ScreenFrame showcase components — captured as element screenshots by the
20	// exact header title text (anchored to the .rounded-2xl app-window root).
21	const FRAMES = [
22	  { file: "server-dashboard.png",       url: "/",              title: "web-prod-01 · sgp1" },
23	  { file: "mail-inbox.png",             url: "/",              title: "you@yourbrand.com" },
24	  { file: "dns-manager.png",            url: "/",              title: "DNS · yourbrand.com" },
25	  { file: "migration-center.png",       url: "/",              title: "Nxeon · Migration" },
26	  { file: "game-servers.png",           url: "/game-servers",  title: "Minecraft · survival-smp" },
27	  { file: "block-storage-volumes.png",  url: "/block-storage", title: "Volumes" },
28	  { file: "ai-builder.png",             url: "/features",      title: "Claude · connected to web-prod-01" },
29	];
30	
31	// Non-frame element captures via CSS selector.
32	const SELECTORS = [
33	  { file: "deploy-wizard.png",    url: "/",                       sel: ".glass.rounded-2xl" },
34	  { file: "pricing-plans.png",    url: "/pricing",                sel: "div.grid.xl\\:grid-cols-4" },
35	  { file: "blog-index.png",       url: "/blog",                   sel: "div.grid.lg\\:grid-cols-3", maxH: 1120 },
36	  { file: "domain-generator.png", url: "/tools/domain-generator", sel: "section.relative .card" },
37	  { file: "free-tools.png",       url: "/tools",                  sel: "div.grid.lg\\:grid-cols-3.mt-10" },
38	];
39	
40	const results = [];
41	
42	async function settle(page, url) {
43	  await page.goto(BASE + url, { waitUntil: "networkidle", timeout: 60000 }).catch(() => {});
44	  await page.evaluate(() => window.scrollTo(0, 0));
45	  await sleep(700);
46	}
47	
48	async function shoot(loc, file, maxH) {
49	  const path = join(OUT, file);
50	  await loc.scrollIntoViewIfNeeded({ timeout: 8000 });
51	  await sleep(1100); // Reveal opacity/transform + bar animations settle
52	  if (maxH) {
53	    // Cap very tall page sections: clip to the top maxH CSS px of the element.
54	    const box = await loc.boundingBox();
55	    if (box && box.height > maxH) {
56	      await loc.page().screenshot({
57	        path,
58	        clip: { x: box.x, y: box.y, width: box.width, height: maxH },
59	      });
60	    } else {
61	      await loc.screenshot({ path });
62	    }
63	  } else {
64	    await loc.screenshot({ path });
65	  }
66	  const kb = statSync(path).size / 1024;
67	  const ok = kb > 15;
68	  if (!ok && existsSync(path)) unlinkSync(path);
69	  results.push({ file, ok, kb: Math.round(kb) });
70	  console.log(`${ok ? "OK " : "BAD"}  ${file.padEnd(28)} ${Math.round(kb)}KB`);
71	  return ok;
72	}
73	
74	const run = async () => {
75	  const browser = await chromium.launch();
76	  const ctx = await browser.newContext({
77	    viewport: { width: 1440, height: 900 },
78	    deviceScaleFactor: 2,
79	    reducedMotion: "reduce", // rest looping mocks on a clean, deterministic frame
80	  });
81	  // Pre-record cookie consent so the bottom banner never overlaps captures.
82	  await ctx.addCookies([
83	    { name: "nxeon_cookie_consent", value: "necessary", domain: new URL(BASE).hostname, path: "/" },
84	  ]);
85	  const page = await ctx.newPage();
86	
87	  for (const t of FRAMES) {
88	    try {
89	      await settle(page, t.url);
90	      const loc = page
91	        .locator("div.rounded-2xl")
92	        .filter({ has: page.locator(".truncate", { hasText: t.title }) })
93	        .first();
94	      await loc.waitFor({ state: "visible", timeout: 15000 });
95	      await shoot(loc, t.file);
96	    } catch (e) {
97	      console.log(`ERR  ${t.file}: ${e.message.split("\n")[0]}`);
98	      results.push({ file: t.file, ok: false, kb: 0 });
99	    }
100	  }
101	
102	  for (const t of SELECTORS) {
103	    try {
104	      await settle(page, t.url);
105	      const loc = page.locator(t.sel).first();
106	      await loc.waitFor({ state: "visible", timeout: 15000 });
107	      await shoot(loc, t.file, t.maxH);
108	    } catch (e) {
109	      console.log(`ERR  ${t.file}: ${e.message.split("\n")[0]}`);
110	      results.push({ file: t.file, ok: false, kb: 0 });
111	    }
112	  }
113	
114	  await browser.close();
115	  const good = results.filter((r) => r.ok);
116	  console.log(`\n=== ${good.length}/${results.length} captured ===`);
117	  console.log(good.map((r) => "/blog/screenshots/" + r.file).join("\n"));
118	};
119	
120	run().catch((e) => {
121	  console.error(e);
122	  process.exit(1);
123	});
