// One-off verification script for the new Node lease-cost/MRR/margin UI on
// /admin/nodes. Runs against STAGING (staging.revsports.ca), never production.
// Steps: log in as staging admin -> screenshot initial state -> edit one
// node's lease cost -> verify save+reload+margin -> revert to blank -> verify.
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";

const BASE = "https://staging.revsports.ca";
const OUT = "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/shots";
mkdirSync(OUT, { recursive: true });

const EMAIL = "admin@nxeon.local";
const PASSWORD = "I7eTwwinDLjbPD57";

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const run = async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({
    viewport: { width: 1440, height: 1000 },
    deviceScaleFactor: 2,
    ignoreHTTPSErrors: true,
  });
  const page = await ctx.newPage();

  console.log("Logging in...");
  await page.goto(BASE + "/login", { waitUntil: "networkidle" });
  await page.fill('input[name="email"], input[type="email"]', EMAIL);
  await page.fill('input[name="password"], input[type="password"]', PASSWORD);
  await page.click('button[type="submit"]');
  await page.waitForLoadState("networkidle");
  console.log("Post-login URL:", page.url());

  await page.goto(BASE + "/admin/nodes", { waitUntil: "networkidle" });
  await sleep(800);
  console.log("Nodes page URL:", page.url());
  await page.screenshot({ path: `${OUT}/1-initial.png`, fullPage: true });
  console.log("Captured initial screenshot.");

  // Dump the text content of the page to inspect structure/values
  const bodyText = await page.evaluate(() => document.body.innerText);
  console.log("=== PAGE TEXT (first 3000 chars) ===");
  console.log(bodyText.slice(0, 3000));

  await browser.close();
};

run().catch((e) => {
  console.error("FAILED:", e);
  process.exit(1);
});

