1	import { redirect } from "next/navigation";
2	import { LoginForm } from "@/components/AuthForms";
3	import { AuthShell } from "@/components/marketing/AuthShell";
4	import { realUser } from "@/lib/auth";
5	import { isStaff } from "@/lib/rbac";
6	import { googleOauthConfigured } from "@/lib/google-oauth";
7	
8	/**
9	 * Dedicated login for the admin subdomain — app/admin/layout.tsx renders
10	 * this bare (no Shell, no auth requirement) for exactly this one sub-route;
11	 * everywhere else under /admin requires a signed-in ADMIN/SUPPORT/BILLING
12	 * account. Kept separate from the customer-facing /login (unreachable on
13	 * this host at all — see middleware.ts) so nobody lands on VPS-pitch copy
14	 * or a "Create account" link that makes no sense for an internal console.
15	 */
16	export default async function AdminLoginPage({
17	  searchParams,
18	}: {
19	  searchParams: Promise<{ error?: string }>;
20	}) {
21	  const { error } = await searchParams;
22	
23	  // Already signed in as staff? Nothing to do here.
24	  const user = await realUser();
25	  if (user && isStaff(user.role)) redirect("/admin");
26	
27	  return (
28	    <AuthShell heading="Nxeon Ops" sub="Sign in to the operations console." bullets={["Staff and admin accounts only", "Every action is audit-logged", "Contact the owner if you've lost access"]}>
29	      <LoginForm
30	        showRegisterLink={false}
31	        googleEnabled={googleOauthConfigured()}
32	        googleError={error === "account_suspended" ? "This account is suspended." : undefined}
33	      />
34	    </AuthShell>
35	  );
36	}
